  assert.ok(src.includes('function fnv1a64(s)'), 'wal-export.js absent on this tip — the doctor-shaped WAL lane is not shipped');
  const mod = { exports: {} };
  new Function('module', 'require', 'process', src + '\nif(false){}')(mod, require, { main: {} });
  return mod.exports;
}

