'use strict';
// R45 birth seal — prerun-coev.js now ends by sealing the C1 ledger rows it
// just wrote (the birth rows behind checkpoints/coev.js) into a stone-v1
// forward chain. Canonical stone source: SuperInstance/quilt-stone stone.mjs
// + STONE-SPEC.md §4.6 (citation named in-repo; referral edge PENDING per
// weight law). The seal is verified BEFORE write: the repo's own mirror
// first, then quilt-stone's OWN verifyChain when QUILT_STONE_DIR names a
// checkout. Any refusal is loud: `stone: SEAL/REFUSED` + exit 1, no file.
// The receipt is not a new training artifact; it is the birth receipt over
// the C1 ledger rows that make checkpoints/coev.js reproducible.

const fs = require("fs");
const path = require("path");
const crypto = require("crypto");
const PQ = require("../core.js");
const WAL = require("./wal-export.js");

const SEED = 20260924;
const POP = 24;
const GENS = 120;
const OUT = path.join(__dirname, "..", "checkpoints", "coev.js");
const SEAL_OUT = path.join(__dirname, "..", "checkpoints", "coev-stone-v1.json");
const STONE_SOURCE = "tools/prerun-coev.js canonical coev birth seal (Round 45)";

// The ledger rows are the artifact's birth rows: one hash-chained head-to-head
// receipt per generation, exactly as written into checkpoints/coev.js.
function birthRows(ledgerRows) {
  return ledgerRows.map((row) => ({
    op: "LINK",
    cell: "pq/prerun-coev-birth",
    args: {
      gen: row.gen,
      sId: row.sId,
      eId: row.eId,
      outcome: row.outcome,
      frames: row.frames,
      sFit: row.sFit,
      eFit: row.eFit,
      loserId: row.loserId,
      prev: row.prev,
      hash: row.hash,
    },
  }));
}

function buildCoevBirthSeal(ledgerRows) {
  return WAL.toStoneV1(
    { tool: "pong-quilt", source: STONE_SOURCE },
    birthRows(ledgerRows));
}

// verify BEFORE write — mirror first (offline, always), live second (only
// when a checkout is named), never a hand-rolled stand-in presented as stone.
async function writeVerifiedSeal(seal, sealOut) {
  const mirror = WAL.verifyStoneV1(seal);
  if (!mirror.ok) {
    console.error(`stone: SEAL/REFUSED mirror verifyChain ${JSON.stringify(mirror)}`);
    process.exit(1);
  }

  const stone = await WAL.loadStone();
  if (!stone) {
    return "mirror-only receipt, labeled (set QUILT_STONE_DIR to open quilt-stone live seam)";
  }

  const live = stone.verifyChain(seal);
  if (!live.ok) {
    console.error(`stone: SEAL/REFUSED live stone.mjs verifyChain ${JSON.stringify(live)}`);
    process.exit(1);
  }
  return "live stone.mjs verifyChain: ok";
}

async function sealCoevBirth(ledgerRows, sealOut = SEAL_OUT) {
  const seal = buildCoevBirthSeal(ledgerRows);
  const liveNote = await writeVerifiedSeal(seal, sealOut);
  fs.writeFileSync(sealOut, JSON.stringify(seal, null, 1) + "\n");
  console.log(`stone: sealed ${seal.length - 1} coev birth rows -> ${path.relative(process.cwd(), sealOut)}; mirror ok; ${liveNote}`);
  return seal;
}

if (require.main === module) {
  // Drop both stale outputs before the run: a prior birth seal must never be
  // mistaken for this run's receipt if the evolution is interrupted.
  fs.rmSync(OUT, { force: true });
  fs.rmSync(SEAL_OUT, { force: true });

  const rand = PQ.rng(SEED);
  const t0 = Date.now();
  let popS = Array.from({ length: POP }, () => PQ.makeNet(rand));
  let popE = Array.from({ length: POP }, () => PQ.makeNet(rand));
  const ledger = PQ.makeLedger(GENS + 1);
  let sChamp = { net: popS[0] }, eChamp = { net: popE[0] }, last = null;
  const probe = PQ.playAdv(popS[0], popE[0], rand, 1200);
  last = probe.outcome;
  ledger.write({ gen: 0, sId: PQ.netId(popS[0]), eId: PQ.netId(popE[0]), outcome: probe.outcome,
                 frames: probe.frames, sFit: probe.sFitness, eFit: probe.eFitness });
  for (let gen = 1; gen <= GENS; gen++) {
    const scoredS = popS.map((net) => { const r = PQ.playAdv(net, eChamp.net, rand, 1200);
      return { net, sFitness: r.sFitness }; });
    const scoredE = popE.map((net) => { const r = PQ.playAdv(sChamp.net, net, rand, 1200);
      return { net, eFitness: r.eFitness }; });
    const bred = PQ.runCoevGeneration(popS, popE, scoredS, scoredE, rand, PQ.DEFAULTS.sigma, last);
    popS = bred.popS; popE = bred.popE;
    const h2h = PQ.playAdv(bred.sChamp.net, bred.eChamp.net, rand, 1200);
    sChamp = { net: bred.sChamp.net }; eChamp = { net: bred.eChamp.net };
    last = h2h.outcome;
    ledger.write({ gen, sId: PQ.netId(sChamp.net), eId: PQ.netId(eChamp.net), outcome: h2h.outcome,
                   frames: h2h.frames, sFit: h2h.sFitness, eFit: h2h.eFitness, loserId: bred.loserId });
    if (gen % 20 === 0 || gen === GENS) console.log(`coev: gen ${gen}/${GENS}  h2h ${h2h.outcome} ${h2h.frames}f`);
  }
  const js = "window.PONG_QUILT_COEV=" + JSON.stringify({
    seed: SEED, pop: POP, gens: GENS, defaults: PQ.DEFAULTS,
    sChamp: { id: PQ.netId(sChamp.net), fitness: sChamp.fitness, net: sChamp.net },
    eChamp: { id: PQ.netId(eChamp.net), fitness: eChamp.fitness, net: eChamp.net },
    ledger: ledger.items(), last,
  }) + ";\n";
  fs.writeFileSync(OUT, js);
  const md5 = crypto.createHash("md5").update(js).digest("hex");
  console.log(`coev: ${GENS} gens x ${POP}+${POP} nets -> ${path.relative(process.cwd(), OUT)}`);
  console.log(`md5  coev.js  ${md5}  (run again — must be identical)`);
  sealCoevBirth(ledger.items()).catch((err) => {
    console.error("stone: SEAL/REFUSED async seal failure:", (err && err.stack) || err);
    process.exit(1);
  });
}

module.exports = { birthRows, buildCoevBirthSeal, writeVerifiedSeal, sealCoevBirth,
                   OUT, SEAL_OUT, STONE_SOURCE };

pong-quilt-main/tools/prerun.js:
// Pre-run the quilt: evolve real checkpoints (L0 random, L1 mid, L2 near-human)
// with the SAME core the browser runs. Output = checkpoint JS files the demo
// loads, so "pick up from a real starting state" is literally true.
//
// Edge-ML round (branch edge-ml-crush, inspired by SuperInstance/quilt-edge-ml):
//  - evaluation streams through PQ.makeEvaluator (their out-of-core pattern);
//    only the bounded elite archive + stats survive each generation.
//  - champion fitness accrues in a PQ.makeRing (their ring_buffer pattern) and
//    is emitted as checkpoints/curve.json — the fitness curve as a real artifact.
//  - black swans draw from the seeded rng, so this script is byte-reproducible:
//    same DEFAULTS.seed -> identical checkpoint bytes. Verified by running
//    twice and diffing (see PLAYLOG Round 2).
// Round 3 (branch round-3-builder): fitness = frames + hits*100 (HIT_WEIGHT),
// so a 0-hit luck champion can never top a hitter (honesty pass). Checkpoints
// regenerated under the new weights; md5 of every emitted file is printed so
// provenance is a checksum, not a promise.
// Round 21 (branch r21-quantum-coin-tiebreak): equal-fitness champion ties are
//  broken by a RECEIPTED QUANTUM COIN, citing SuperInstance/quilt-quant's
//  coin-toss-v1 (live moth-quantum API, lab/play.mjs — job-id journaled, mock
//  flag explicit). CI has no network: the coin is the SEEDED MOCK stand-in,
//  drawn from the same `rand` stream that makes this script byte-reproducible,
//  and every flip lands in checkpoints/curve.json as {gen, incumbent, challenger,
//  coin, engine: 'coin-toss-v1', live: false}. Honesty: mock is labeled, never
//  laundered as live quantum entropy. Weight law: a merged PR here citing
//  quilt-quant's coin = candidate VERIFIED referral edge qt-quant -> pong-quilt.
const PQ = require("../core.js");
const fs = require("fs"), path = require("path");
const crypto = require("crypto");
const D = PQ.DEFAULTS;
const rand = PQ.rng(D.seed);
const TOTAL_GENS = 260, CURVE_SAMPLES = 20;
let pop = Array.from({ length: D.popSize }, () => PQ.makeNet(rand));
const champRing = PQ.makeRing(TOTAL_GENS + 1); // one slot per generation, bounded
const tieReceipts = []; // every coin flip (keeps AND swaps), curve.json-bound
let curGen = 0;
// The quantum-coin tiebreak (seeded mock of quilt-quant coin-toss-v1):
// on equal fitness, incumbent keeps on heads, challenger takes on tails.
// R22 honesty fix: EVERY flip is journaled — a heads burn that keeps the
// incumbent leaves a receipt just like a tails swap. The R21 journal was
// asymmetric (tails-only): 51% of coin events (93 of 182 flips in the
// seeded run) were unrecorded, so "89 flips" undercounted the real stream
// and the receipt could not be audited for keeps. Repro: instrumented run
// of the R21 code counts 182 flips vs 89 receipts.
function quantumCoinTiebreak(rec, incumbent) {
  const heads = rand() < 0.5; // one burn of the shared seeded stream either way
  tieReceipts.push({ gen: curGen, incumbent: incumbent.index, challenger: rec.index,
                     coin: heads ? 'H' : 'T', swap: !heads,
                     engine: 'coin-toss-v1', live: false,
                     citation: 'SuperInstance/quilt-quant lab/play.mjs coin-toss-v1' });
  return !heads; // H: incumbent keeps (false); T: challenger takes (true)
}
let scored = null;
function evaluate() { // stream the population; retain elites only (flat memory)
  const ev = PQ.makeEvaluator(pop, (net) => PQ.playOne(net, rand),
                              { eliteK: D.elites, onTie: quantumCoinTiebreak });
  let snap; // each step() returns a snapshot; the last one is the generation result
  while (!ev.done) snap = ev.step(8); // batch size is a scheduling detail, not semantics
  return snap;
}
function recordChamp(gen) {
  champRing.write({ gen, fitness: scored.best.fitness, frames: scored.best.frames,
                    hits: scored.best.hits, maxSpeed: +scored.best.maxSpeed.toFixed(3) });
}
function emit(level, gen) {
  const best = scored.best;
  const js = "window.PONG_QUILT_CHECKPOINTS=window.PONG_QUILT_CHECKPOINTS||{};\n" +
    `window.PONG_QUILT_CHECKPOINTS["${level}"]=` + JSON.stringify({
      gen, bestFitness: best.fitness, bestFrames: best.frames, bestHits: best.hits,
      maxSpeed: +best.maxSpeed.toFixed(3), pop }) + ";";
  fs.writeFileSync(path.join(__dirname, "..", "checkpoints", `${level}.js`), js);
  console.log(`${level}: gen ${gen} best fitness ${best.fitness | 0} ` +
    `(frames ${best.frames}, hits ${best.hits}, speed x${best.maxSpeed.toFixed(2)})`);
}
function emitCurve() {
  const items = champRing.items();
  const step = Math.max(1, Math.floor(items.length / CURVE_SAMPLES));
  const samples = items.filter((_, i) => i % step === 0 || i === items.length - 1)
    .map(({ gen, fitness }) => ({ gen, fitness }));
  fs.writeFileSync(path.join(__dirname, "..", "checkpoints", "curve.json"),
    JSON.stringify({ seed: D.seed, gens: TOTAL_GENS, ringWrites: champRing.writes,
                     tiebreaks: tieReceipts, samples }, null, 1));
  const swaps = tieReceipts.filter(t => t.swap).length;
  console.log(`curve: ${champRing.writes} generations sampled to ${samples.length} points -> checkpoints/curve.json` +
    (tieReceipts.length ? `; ${tieReceipts.length} quantum-coin flip(s), ${swaps} swap(s)` : "; no champion ties"));
}
fs.mkdirSync(path.join(__dirname, "..", "checkpoints"), { recursive: true });
scored = evaluate();
recordChamp(0);
emit("level0", 0);
for (let g = 1; g <= 60; g++) {
  curGen = g;
  pop = PQ.runGeneration(pop, scored.elites, rand, D.sigma);
  scored = evaluate();
  recordChamp(g);
}
emit("level1", 60);
for (let g = 61; g <= TOTAL_GENS; g++) {
  curGen = g;
  pop = PQ.runGeneration(pop, scored.elites, rand, D.sigma);
  scored = evaluate();
  recordChamp(g);
}
emit("level2", TOTAL_GENS);
emitCurve();

// ---------------------------------------------------------------------------
// R37 (branch r37-prerun-stone-seal): the canonical checkpoints are sealed
// IN STONE-V1 AT BIRTH. R35's merge-gate lesson was "the stone lens opens on
// the merge gate" — this round moves the lens to birth: every prerun run
// ends by sealing the four artifacts it just wrote (curve.json, level0/1/2)
// into checkpoints/stone-v1.json, a stone-v1 forward chain verified by
// SuperInstance/quilt-stone stone.mjs (STONE-SPEC.md §4.6, the fleet's
// canonical verifier) whose payload rows carry {file, md5} — provenance as
// a chained receipt, not a promise. Sealing reuses tools/wal-export.js's toStoneV1 so there is
// exactly one stone-v1 dialect in the repo.
// HONESTY CONTRACT (same shape as the R36 seam): the chain is verified
// BEFORE it is written — the offline mirror first, and quilt-stone's OWN
// stone.mjs via loadStone() when a checkout is named (QUILT_STONE_DIR);
// absent → the mirror-only receipt is printed labeled, never a hand-rolled
// stand-in presented as stone, and never a silent skip. Any refusal → no
// seal file, exit 1 (FAIL-first: a broken receipt must brick the run loudly).
// The seal is NOT one of the canonical five — it is the receipt OVER them,
// so a stale seal is dropped before the provenance loop to keep that loop's
// output exactly the artifacts this run owns.
// ---------------------------------------------------------------------------
const cpDir = path.join(__dirname, "..", "checkpoints");
fs.rmSync(path.join(cpDir, "stone-v1.json"), { force: true }); // prior run's seal, if any
fs.rmSync(path.join(cpDir, "stone-v1.signed.json"), { force: true }); // R39: prior run's staple, if any
for (const f of fs.readdirSync(cpDir).sort()) {
  const md5 = crypto.createHash("md5").update(fs.readFileSync(path.join(cpDir, f))).digest("hex");
  console.log(`md5  ${f}  ${md5}`);
}
console.log("checkpoints written:", fs.readdirSync(cpDir).join(", "));

(async () => { // R37 stone seal — async tail: loadStone()'s dynamic import is async
  const WALX = require("./wal-export.js");
  const sealFiles = ["curve.json", "level0.js", "level1.js", "level2.js"];
  const rows = sealFiles.map(f => ({ op: "LINK", cell: "pq/prerun-checkpoint",
    args: { file: f, md5: crypto.createHash("md5").update(fs.readFileSync(path.join(cpDir, f))).digest("hex") } }));
  const seal = WALX.toStoneV1(
    { tool: "pong-quilt", source: "tools/prerun.js canonical checkpoint seal (Round 37)" }, rows);
  const mirror = WALX.verifyStoneV1(seal); // verify BEFORE write (R30 lesson: non-ok → no file saved)
  if (!mirror.ok) {
    console.error(`stone: SEAL/REFUSED mirror verify failed ${JSON.stringify(mirror)}`);
    process.exit(1);
  }
  const stone = await WALX.loadStone(); // live cross-check only when a checkout is named
  let liveNote = "live stone.mjs: no checkout named (QUILT_STONE_DIR) — mirror-only receipt, labeled";
  if (stone) {
    const v = stone.verifyChain(seal);
    if (!v.ok) {
      console.error(`stone: SEAL/REFUSED canonical verifier rejects the seal ${JSON.stringify(v)}`);
      process.exit(1);
    }
    liveNote = `live stone.mjs verifyChain: ok (links ${v.links})`;
  }
  fs.writeFileSync(path.join(cpDir, "stone-v1.json"), JSON.stringify(seal, null, 1) + "\n");
  console.log(`stone: sealed ${rows.length} checkpoint rows -> checkpoints/stone-v1.json; mirror ok; ${liveNote}`);

  // R39 (branch r39-stone-sign-pilot): STONE-V2-PILOTS first sign pilot —
  // the producer staples the birth-seal chain's tip with an ed25519
  // signature (SuperInstance/quilt-stone signTip/verifyTipSignature, the
  // stone-v2 sign lane; STONE-SPEC.md §4.6.2). Keys live with the PRODUCER:
  // QUILT_STONE_SIGN_KEY may name a PEM private key file for a stable
  // producer identity; absent, an ephemeral keypair is generated per run
  // and the staple is LABELED ephemeral — never presented as standing
  // identity. The staple ships CLOSED: when the named checkout has no
  // signTip (the sign lane is not merged there yet) nothing is written and
  // the skip is printed labeled, never silent. The signed chain is verified
  // BEFORE write (verifyTipSignature with the producer public key), and a
  // refused staple bricks the run exactly like a refused seal.
  if (!stone || typeof stone.signTip !== "function") {
    console.log("stone: sign lane not in named checkout (quilt-stone signTip absent) — staple skipped, labeled");
    return;
  }
  const keyPath = process.env.QUILT_STONE_SIGN_KEY || null;
  let privateKey, publicKeyPem, ephemeral;
  if (keyPath) {
    privateKey = crypto.createPrivateKey(fs.readFileSync(keyPath));
    publicKeyPem = crypto.createPublicKey(privateKey).export({ type: "spki", format: "pem" });
    ephemeral = false;
  } else {
    const pair = crypto.generateKeyPairSync("ed25519");
    privateKey = pair.privateKey;
    publicKeyPem = pair.publicKey.export({ type: "spki", format: "pem" });
    ephemeral = true;
  }
  const signed = seal.map(r => ({ ...r })); // staple a copy; the unsigned birth seal stays canonical
  stone.signTip(signed, privateKey, { key_id: "pq-prerun-sign-pilot", signer_role: "producer" });
  const sig = stone.verifyTipSignature(signed, publicKeyPem);
  if (!sig.ok) {
    console.error(`stone: SIGN/REFUSED verifyTipSignature rejects the staple ${JSON.stringify(sig)}`);
    process.exit(1);
  }
  fs.writeFileSync(path.join(cpDir, "stone-v1.signed.json"), JSON.stringify({
    tool: "pong-quilt", round: "R39", source: "tools/prerun.js birth-seal tip staple (STONE-V2-PILOTS first sign pilot)",
    key: { ephemeral, public: publicKeyPem },
    verify: { ok: sig.ok, tip: sig.tip, signer: sig.signer },
    chain: signed,
  }, null, 1) + "\n");
  console.log(`stone: stapled birth-seal tip ${sig.tip} -> checkpoints/stone-v1.signed.json; verifyTipSignature ok` +
    (ephemeral ? " (ephemeral producer key, labeled)" : ` (producer key ${keyPath})`));
})().catch(e => { console.error("stone: SEAL/REFUSED", e && e.message ? e.message : e); process.exit(1); });

pong-quilt-main/tools/wal-export.js:
// R26 — WAL export in the fleet five-opcode quilt shape (the quilt-doctor
// consumer lane). The page's receipt panel and makeLedger chain with the
// page hash (hash8, h*31 — a panel display hash, never claimed otherwise).
// quilt-doctor's substrate (SuperInstance/quilt-doctor quilt_doctor/substrate.py,
// canonical producer SuperInstance/git-agent PR #1's quilt_emit) speaks the
// fleet WAL: BIND/LINK/VIEW lines, fnv1a-64 chained, replayable. This tool
// re-anchors any row list into THAT shape, so the doctor's own verify() can
// consume pong-quilt's receipts without a bespoke adapter. Live cross-tool
// receipt (Round 26 PLAYLOG): the export is verified by quilt_doctor's own
// QuiltSubstrate.verify() run against the emitted file. Weight law: a merged
// quilt-doctor PR consuming this export and citing pong-quilt = candidate
// VERIFIED referral edge pq -> quilt-doctor.
'use strict';

// fnv1a-64, exactly as quilt_doctor/substrate.py implements it
// (FNV_OFFSET 0xcbf29ce484222325, PRIME 0x100000001b3, %016x).
function fnv1a64(s) {
  // BigInt: the prime 0x100000001b3 is 40 bits — Math.imul would truncate it.
  let h = 0xcbf29ce484222325n;
  for (let i = 0; i < s.length; i++) {
    h = ((h ^ BigInt(s.charCodeAt(i))) * 0x100000001b3n) & 0xffffffffffffffffn;
  }
  return h.toString(16).padStart(16, '0');
}

// Python json.dumps(sort_keys=True, separators=(",",":")) equivalent:
// keys sorted at EVERY nesting level, no whitespace.
function canonical(d) {
  if (d === null || typeof d !== 'object') return JSON.stringify(d);
  if (Array.isArray(d)) return '[' + d.map(canonical).join(',') + ']';
  const keys = Object.keys(d).sort();
  return '{' + keys.map(k => JSON.stringify(k) + ':' + canonical(d[k])).join(',') + '}';
}

// The five WAL opcodes, vendored by name from the spine
// (git-agent PR #1's quilt_emit — the third VERIFIED edge's target).
const OPS = ['BIND', 'LINK', 'VIEW'];

// rows: [{op, cell, args}, ...] — op must be one of OPS.
// meta: {tool, source} — lands in the BIND genesis row's args.
// Returns the hash-chained line list, exactly the key shape
// {args, cell, hash, op, prev_hash, seq} quilt_doctor/substrate.py writes.
function toQuiltWal(meta, rows) {
  const lines = [];
  const all = [{ op: 'BIND', cell: 'pq/session', args: { tool: meta.tool, source: meta.source } }]
    .concat(rows.map(r => {
      if (!OPS.includes(r.op)) throw new Error('unknown WAL op: ' + r.op);
      return { op: r.op, cell: r.cell, args: r.args };
    }));
  for (let seq = 0; seq < all.length; seq++) {
    const line = { op: all[seq].op, cell: all[seq].cell, args: all[seq].args,
                   seq, prev_hash: seq === 0 ? '0'.repeat(16) : lines[seq - 1].hash };
    line.hash = fnv1a64(canonical(line));
    lines.push(line);
  }
  return lines;
}

// The consumer's verify(), mirrored line-for-line from
// quilt_doctor/substrate.py QuiltSubstrate.verify() — hash_mismatch /
// chain_break / seq_gap divergences, so a pin can prove our export fails
// the doctor's checks exactly when tampered, in the doctor's own vocabulary.
function verifyQuiltWal(lines) {
  let prevHash = '0'.repeat(16);
  const divergences = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const { hash, ...rest } = line;
    if (line.hash !== fnv1a64(canonical(rest)))
      divergences.push({ seq: i, why: 'hash_mismatch' });
    if (line.prev_hash !== prevHash)
      divergences.push({ seq: i, why: 'chain_break' });
    if (line.seq !== i)
      divergences.push({ seq: i, why: 'seq_gap' });
    prevHash = line.hash;
  }
  return { ok: divergences.length === 0, divergences, lines: lines.length };
}

// ---------------------------------------------------------------------------
// R36 — stone-v1 forward format (SuperInstance/quilt-stone, Task 26-b).
// quilt-stone is THE CANONICAL receipt-chain module: one zero-dep verifier
// (stone.mjs) for every repo chain, 42/42 sibling chains conformance-verified.
// House law over there: "a receipt without a chain is a rumor" — and NEW
// chains MUST write stone-v1: row 0 is a stone.header naming its alg, hash =
// sha256Hex over canonicalJSON([prev, row minus row_hash]), genesis
// 'STONE-GENESIS-1' hashed into row 0 (STONE-SPEC.md §4.6). This lane seals
// the SAME five-opcode WAL rows in the stone-v1 forward shape, so pong-quilt
// receipts are directly consumable by the fleet's canonical verifier.
//
// HONESTY CONTRACT (fleet doctrine, same shape as the doctor seam): the live
// cross-check loads quilt-stone's OWN stone.mjs via loadStone() and only when
// an explicit checkout is named (QUILT_STONE_DIR, or opts.dir). Absent → null
// → consumers skip, NEVER a hand-rolled stand-in presented as stone.
// CITATION (referral edge candidate, PENDING per weight law): canonical
// source = SuperInstance/quilt-stone stone.mjs + STONE-SPEC.md §4.6.
// VERIFIED only when a merged PR in the TARGET repo names this citation.
// ---------------------------------------------------------------------------

const STONE_GENESIS = 'STONE-GENESIS-1';

// stone.mjs canonicalJSON, mirrored verbatim (undefined-valued keys SKIPPED —
// the fleet canonical() above keeps them as undefined→omitted-by-JSON, which
// coincides for our rows but NOT for explicit undefined; the mirror is exact
// so cross-tool hashes can never diverge on a serialization subtlety).
function canonicalStone(d) {
  if (d === null || typeof d !== 'object') return JSON.stringify(d ?? null);
  if (Array.isArray(d)) return '[' + d.map(canonicalStone).join(',') + ']';
  const keys = Object.keys(d).filter(k => d[k] !== undefined).sort();
  return '{' + keys.map(k => JSON.stringify(k) + ':' + canonicalStone(d[k])).join(',') + '}';
}

// sha256Hex is node-only (tools/tests). The page WAL seam (Round 30) is
// unchanged — the browser door never calls the stone-v1 lane.
function sha256Hex(s) {
  if (typeof require !== 'function') throw new Error('stone-v1 sealing is node-only; the page WAL seam is unchanged');
  return require('crypto').createHash('sha256').update(s, 'utf8').digest('hex');
}

// rows: [{op, cell, args}, ...] — the same five-opcode WAL ops as toQuiltWal.
// meta: {tool, source} — lands in the stone.header row (self-describing chain).
// Returns stone-v1 rows: row 0 = {kind:'stone.header', alg, genesis, ...},
// payload rows carry {kind:'pq/wal-op', seq (1-based), op, cell, args}, each
// with row_hash = sha256Hex(canonicalJSON([prev, row minus row_hash])).
function toStoneV1(meta, rows) {
  const header = { kind: 'stone.header', alg: 'stone-v1', genesis: STONE_GENESIS,
                   tool: meta.tool, source: meta.source };
  const body = rows.map((r, i) => {
    if (!OPS.includes(r.op)) throw new Error('unknown WAL op: ' + r.op);
    return { kind: 'pq/wal-op', seq: i + 1, op: r.op, cell: r.cell, args: r.args };
  });
  let prev = STONE_GENESIS;
  return [header].concat(body).map(r => {
    const row = Object.assign({}, r);
    const { row_hash, ...rest } = row; // strip if caller re-seals
    row.row_hash = sha256Hex(canonicalStone([prev, rest]));
    prev = row.row_hash;
    return row;
  });
}

// Offline mirror of stone.mjs verifyChain for the stone-v1 dialect, so pins
// trip without a checkout; the live seam (below) is the receipted authority.
function verifyStoneV1(lines) {
  let prev = STONE_GENESIS;
  for (let i = 0; i < lines.length; i++) {
    const row = lines[i];
    const h = row && row.row_hash;
    if (typeof h !== 'string' || !/^[0-9a-f]{64}$/.test(h))
      return { ok: false, at: i, why: 'row_hash form', links: i };
    const { row_hash, ...rest } = row;
    if (sha256Hex(canonicalStone([prev, rest])) !== h)
      return { ok: false, at: i, why: 'hash mismatch', links: i };
    prev = h;
  }
  return { ok: true, at: null, why: null, links: lines.length, tip: lines.length ? prev : null };
}

// Live seam: load quilt-stone's OWN verifier. dir resolution: opts.dir ||
// QUILT_STONE_DIR env; NO relative guess (quilt-stone is brand-new — unlike
// quilt-doctor there is no standing sibling checkout to assume).
// Returns the stone module ({verifyChain, verifyChainFile, detectAlg, ...})
// or null — never throws, never fabricates.
async function loadStone(opts) {
  if (typeof require !== 'function') return null; // browser door: seam closed
  const dir = (opts && opts.dir) || (typeof process !== 'undefined' && process.env && process.env.QUILT_STONE_DIR);
  if (!dir) return null;
  try {
    const m = await import(require('path').join(dir, 'stone.mjs'));
    if (typeof m.verifyChain === 'function') return m;
  } catch (e) { /* absent or unloadable: seam closed */ }
  return null;
}

function walToJsonl(lines) {
  // json.dumps(line, sort_keys=True) equivalent — the replacer-array trick
  // would whitelist NESTED keys too and silently drop args fields; canonical()
  // sorts every level and keeps everything.
  return lines.map(l => canonical(l)).join('\n') + '\n';
}

// Dual load: node (tools, tests) and the page (script tag). The page
// seam (Round 30) needs the SAME exporter the tools pin — one impl, two doors.
const WAL_EXPORT_API = { fnv1a64, canonical, toQuiltWal, verifyQuiltWal, walToJsonl, OPS,
                         toStoneV1, verifyStoneV1, canonicalStone, loadStone, STONE_GENESIS };
if (typeof module !== 'undefined' && module.exports) module.exports = WAL_EXPORT_API;
if (typeof window !== 'undefined') window.QUILT_WAL = WAL_EXPORT_API;

// CLI: node tools/wal-export.js — demo driver, exports the page's demo
// receipt kinds as a doctor-consumable WAL and self-verifies it.
if (typeof require !== 'undefined' && require.main === module) {
  const lines = toQuiltWal(
    { tool: 'pong-quilt', source: 'tools/wal-export.js demo driver (Round 26)' },
    [
      { op: 'LINK', cell: 'pq/receipt', args: { kind: 'L2', move: 1, conf: 0.42, gen: 0 } },
      { op: 'LINK', cell: 'pq/receipt', args: { kind: 'DEATH', move: 0, conf: 0, gen: 3 } },
      { op: 'LINK', cell: 'pq/receipt', args: { kind: 'QA-REFUSAL', move: 0, conf: 0, gen: 3 } },
      { op: 'VIEW', cell: 'pq/projection/eviction', args: { shown: 3, evicted: 41 } },
    ]);
  const report = verifyQuiltWal(lines);
  process.stdout.write(walToJsonl(lines));
  console.error(JSON.stringify(report));
  if (!report.ok) process.exit(1);
}

pong-quilt-main/tools/wal-session.js:
// R26 booked small — the REAL receipt-panel→WAL session driver.
// wal-export.js (Round 26) re-anchors any row list into the fleet WAL, but
// its demo driver hand-writes rows. This driver closes the loop: it plays a
// REAL seeded headless classic-mode session through the same two modules the
// browser panel receipts (core.js step + qa.js suggest — the qa advisor
// lane), collects every receipt the panel would show (advice rows named for
// their source, QA-REFUSAL rows when the pot is below the documented floor,
// DEATH rows at game end), re-anchors them into the doctor-consumable WAL,
// self-verifies with the exporter's own verifyQuiltWal, and writes the
// .jsonl. Seeded: same seed → byte-identical export. Weight law: a merged
// quilt-doctor PR replaying this file and citing pong-quilt = the same
// candidate VERIFIED edge pq -> quilt-doctor, now fed by a real session
// instead of a demo row list.
'use strict';

const PQ = require('../core.js');
const QuantumAudioL2 = require('../qa.js');
const { toQuiltWal, verifyQuiltWal, walToJsonl, toStoneV1, verifyStoneV1, loadStone } = require('./wal-export.js');

// A paced classic-mode session, headless but real: one advice call per
// decisionInterval boundary (the page paces at death/ADVICE_EVERY; pacing
// per decision keeps every advice event receipted without a 150-frame
// gap swallowing the refusal evidence). The pot depletes by 1 per advice
// call, so a long enough session drives QA.suggest below SIM_POT_FLOOR and
// the exhaustion seam receipts QA-REFUSAL for real — the R12 doctrine,
// produced by running, not written by hand.
// opts: { games, maxFramesPerGame, shotsPerBin, deplete }
function runSession(seed, opts = {}) {
  const games = opts.games || 3;
  const maxFrames = opts.maxFramesPerGame || 4000;
  const spb0 = opts.shotsPerBin == null ? 8 : opts.shotsPerBin;
  const deplete = opts.deplete == null ? 1 : opts.deplete;
  const rand = PQ.rng(seed);
  const receipts = [];
  const stats = { seed, games: 0, frames: 0, hits: 0, advice: 0, refusals: 0, deaths: 0 };
  let pot = spb0;
  for (let g = 0; g < games; g++) {
    const game = PQ.newGame(rand);
    stats.games++;
    let alive = true;
    while (alive && game.frames < maxFrames) {
      const s0 = { ballX: game.x, ballY: game.y, velX: game.vx, velY: game.vy,
                   paddleX: game.px, speed: game.speedMul, frames: game.frames, hits: game.hits };
      const s = QuantumAudioL2.suggest(s0, (seed * 31 + g * 997 + game.frames) >>> 0, pot);
      if (s) {
        stats.advice++;
        receipts.push({ kind: s.source || 'qa-sim', move: s.move, conf: s.confidence, gen: g });
        alive = PQ.step(game, s.move, rand);
      } else {
        stats.refusals++;
        receipts.push({ kind: 'QA-REFUSAL', move: 0, conf: 0, gen: g });
        alive = PQ.step(game, 0, rand);
      }
      pot = Math.max(0, pot - deplete);
    }
    stats.frames += game.frames;
    stats.hits += game.hits;
    if (!alive) { stats.deaths++; receipts.push({ kind: 'DEATH', move: 0, conf: 0, gen: g }); }
    pot = spb0; // each new game restores the pot, like the page's fixed control
  }
  return { receipts, stats };
}

// Session → rows. Every collected receipt becomes one LINK pq/receipt row
// (the ledger keeps them all); the export closes with an honest VIEW of the
// session, and — when the ledger exceeds the page panel's 40-row bound — a
// second VIEW admitting the panel's eviction accounting exactly as the page
// renders it ('N shown / M evicted'): the WAL is the unbounded memory, the
// projection admits the bounded display. ONE row builder feeds both the
// five-opcode WAL (sessionToWal) and the stone-v1 seal (sessionToStoneV1,
// Round 38) so the two chains can never disagree about the session.
function sessionRows(session) {
  const { receipts, stats } = session;
  const rows = receipts.map(r => ({ op: 'LINK', cell: 'pq/receipt',
    args: { kind: r.kind, move: r.move, conf: r.conf, gen: r.gen } }));
  rows.push({ op: 'VIEW', cell: 'pq/projection/session',
    args: { seed: stats.seed, games: stats.games, frames: stats.frames, hits: stats.hits,
            advice: stats.advice, refusals: stats.refusals, deaths: stats.deaths } });
  if (receipts.length > 40) {
    rows.push({ op: 'VIEW', cell: 'pq/projection/eviction',
      args: { shown: 40, evicted: receipts.length - 40, bound: 'page panel (index.html receipt())' } });
  }
  return rows;
}

function sessionToWal(session) {
  const { stats } = session;
  return toQuiltWal({ tool: 'pong-quilt',
    source: `tools/wal-session.js (seed ${stats.seed}, ${stats.games} games)` }, sessionRows(session));
}

// Round 38 — the session driver's stone-v1 seal. The session rows are
// re-anchored into quilt-stone's canonical stone-v1 forward format
// (SuperInstance/quilt-stone stone.mjs, STONE-SPEC.md §4.6) using
// wal-export.js's toStoneV1 — exactly one stone-v1 dialect in the repo. The
// seal is the receipt OVER the session WAL, the same shape as the R36
// exporter seam and the R37 prerun seal: verified BEFORE it is written
// (offline mirror first; quilt-stone's OWN stone.mjs via loadStone() when
// QUILT_STONE_DIR names a checkout), any refusal → no file, never a
// hand-rolled stand-in presented as stone.
function sessionToStoneV1(session) {
  const { stats } = session;
  return toStoneV1({ tool: 'pong-quilt',
    source: `tools/wal-session.js stone seal (seed ${stats.seed}, ${stats.games} games)` },
    sessionRows(session));
}

module.exports = { runSession, sessionToWal, sessionToStoneV1, parseCliArgs };

// CLI arg parse (Round 33 — the R32-booked P4): unrecognized positional args,
// unknown flags, and a valueless --out are USAGE errors (stderr + exit 2),
// never silently defaulted and never a raw TypeError from
// fs.writeFileSync(undefined). Exported for unit pins; the glue pin drives
// the real CLI by spawning it.
function parseCliArgs(argv) {
  const USAGE = 'usage: node tools/wal-session.js [seed] [--out PATH] [--stone-out PATH]';
  const fail = (why) => ({ error: USAGE + ' — ' + why });
  let outPath = null;
  let stoneOutPath = null;
  const positional = [];
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--out') {
      const v = argv[i + 1];
      if (v == null || v.startsWith('--')) return fail('--out requires a PATH value');
      outPath = v;
      i++;
    } else if (a === '--stone-out') {
      const v = argv[i + 1];
      if (v == null || v.startsWith('--')) return fail('--stone-out requires a PATH value');
      stoneOutPath = v;
      i++;
    } else if (a.startsWith('--')) {
      return fail('unrecognized flag: ' + a);
    } else {
      positional.push(a);
    }
  }
  if (positional.length > 1)
    return fail('unrecognized argument: ' + positional.slice(1).join(' '));
  // R43 (R40 playtest finding 3): an explicit seed is used verbatim — 0 is a
  // real seed (PQ.rng(0) is a valid LCG stream), never falsy-collapsed into
  // the default by `|| 20260926`; a non-integer seed is a usage error like
  // every other R33 misuse, never a silent default. The full-string integer
  // check also refuses parseInt's silent-prefix parses ('0x10' -> 0).
  let seed = 20260926;
  if (positional.length) {
    const arg = positional[0];
    if (!/^-?\d+$/.test(arg))
      return fail('seed must be an integer, got: ' + arg);
    seed = parseInt(arg, 10);
  }
  return { seed, outPath, stoneOutPath };
}

// CLI: node tools/wal-session.js [seed] [--out PATH] [--stone-out PATH] —
// plays the session, self-verifies the WAL, prints the verify report to
// stderr and the JSONL to stdout (or --out PATH). Exit 1 on any divergence;
// exit 2 + usage on arg misuse. Round 38: --stone-out PATH additionally
// seals the session rows in stone-v1 (quilt-stone canonical format), verified
// BEFORE the file is written — offline mirror always, quilt-stone's OWN
// stone.mjs when QUILT_STONE_DIR names a checkout; a refusal bricks the run
// (exit 1, no seal file), never a silent skip.
if (require.main === module) {
  const parsed = parseCliArgs(process.argv.slice(2));
  if (parsed.error) {
    console.error(parsed.error);
    process.exit(2);
  }
  const { seed, outPath, stoneOutPath } = parsed;
  const session = runSession(seed);
  const lines = sessionToWal(session);
  const report = verifyQuiltWal(lines);
  const fs = require('fs');
  if (outPath) fs.writeFileSync(outPath, walToJsonl(lines));
  else process.stdout.write(walToJsonl(lines));
  console.error(JSON.stringify({ ...report, receipts: session.receipts.length, stats: session.stats }));
  if (!report.ok) process.exit(1);
  if (stoneOutPath) {
    (async () => {
      const WALX = require('./wal-export.js');
      const seal = sessionToStoneV1(session);
      const mirror = WALX.verifyStoneV1(seal); // verify BEFORE write (R30 lesson)
      if (!mirror.ok) {
        console.error(`stone: SEAL/REFUSED mirror verify failed ${JSON.stringify(mirror)}`);
        process.exit(1);
      }
      const stone = await WALX.loadStone(); // live cross-check only when a checkout is named
      let liveNote = 'live stone.mjs: no checkout named (QUILT_STONE_DIR) — mirror-only receipt, labeled';
      if (stone) {
        const v = stone.verifyChain(seal);
        if (!v.ok) {
          console.error(`stone: SEAL/REFUSED canonical verifier rejects the seal ${JSON.stringify(v)}`);
          process.exit(1);
        }
        liveNote = `live stone.mjs verifyChain: ok (links ${v.links})`;
      }
      fs.writeFileSync(stoneOutPath, walToJsonl(seal));
      console.error(`stone: sealed ${seal.length - 1} session rows -> ${stoneOutPath}; mirror ok; ${liveNote}`);
    })().catch(e => { console.error('stone: SEAL/REFUSED', e && e.message ? e.message : e); process.exit(1); });
  }
}
